        (std::fabs(norm_state[0]) + std::fabs(norm_state[1]) + std::fabs(norm_state[2])) / 3.0f;
    const float linf_norm =
        std::fmax(std::fabs(norm_state[0]), std::fmax(std::fabs(norm_state[1]), std::fabs(norm_state[2])));
