def rotation(theta: float) -> np.ndarray:
    c, s = np.cos(theta), np.sin(theta)
    return np.array([[c, -s], [s, c]], dtype=float)


def connected_components(nodes: list[str], edges: list[tuple[str, str]]) -> list[set[str]]:
    parent = {n: n for n in nodes}

    def find(x: str) -> str:
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    for s, t in edges:
        if s in parent and t in parent:
            rs, rt = find(s), find(t)
            if rs != rt:
                parent[rt] = rs
    comps: dict[str, set[str]] = {}
    for n in nodes:
        r = find(n)
        comps.setdefault(r, set()).add(n)
    return list(comps.values())


def fundamental_cycles(
    nodes: list[str], edges: list[tuple[str, str]]
) -> list[list[tuple[str, str]]]:
    parent: dict[str, str | None] = {n: None for n in nodes}
    depth = {n: 0 for n in nodes}
    tree_edges: set[frozenset[str]] = set()
    visited: set[str] = set()
    adj: dict[str, list[str]] = {n: [] for n in nodes}
    for s, t in edges:
        adj[s].append(t)
        adj[t].append(s)

    def dfs(u: str, p: str | None) -> None:
        visited.add(u)
        for v in adj[u]:
            if v == p:
                continue
            if v not in visited:
                parent[v] = u
                depth[v] = depth[u] + 1
                tree_edges.add(frozenset([u, v]))
                dfs(v, u)

    for n in nodes:
        if n not in visited:
            dfs(n, None)

    cycles: list[list[tuple[str, str]]] = []
    for s, t in edges:
        e = frozenset([s, t])
        if e in tree_edges:
            continue
        path_s: list[str] = []
        path_t: list[str] = []
        a, b = s, t
        while a != b:
            if depth[a] >= depth[b]:
                path_s.append(a)
                a = parent[a]  # type: ignore
            if a != b and depth[b] > depth[a]:
                path_t.append(b)
                b = parent[b]  # type: ignore
            if a != b and depth[a] == depth[b]:
                path_s.append(a)
                path_t.append(b)
                a = parent[a]  # type: ignore
                b = parent[b]  # type: ignore
        lca = a
        chain = path_s + [lca] + list(reversed(path_t))
        cyc_edges = [(chain[i], chain[i + 1]) for i in range(len(chain) - 1)]
        cyc_edges.append((s, t))
        cycles.append(cyc_edges)
    return cycles


