        Hol = np.eye(d)
        edge_list = []
        for a, b in cyc:
            em = em_by_key.get(_edge_key(a, b))
            if em is None:
                continue
            if em.source == a and em.target == b:
                Hol = em.matrix @ Hol
            else:
                Hol = em.matrix.T @ Hol
            edge_list.append({"source": em.source, "target": em.target, "theta": em.theta})
        dev = float(norm(Hol - np.eye(d), ord="fro"))
        if dev > 1e-6:
            relax_scores = []
            for em in edge_maps:
                Hol2 = np.eye(d)
                for a, b in cyc:
                    em2 = em_by_key[_edge_key(a, b)]
                    R = np.eye(d) if em2 is em else em2.matrix
                    if em2.source == a and em2.target == b:
                        Hol2 = R @ Hol2
                    else:
                        Hol2 = R.T @ Hol2
                dev2 = float(norm(Hol2 - np.eye(d), ord="fro"))
                relax_scores.append({
                    "source": em.source, "target": em.target, "theta": em.theta,
                    "holonomy_after_relax": dev2, "reduction": dev - dev2,
                })
            relax_scores.sort(key=lambda z: z["reduction"], reverse=True)
            bad_cycles.append({
                "cycle_id": ci, "edges": edge_list, "holonomy_deviation": dev,
                "best_relax": relax_scores[0] if relax_scores else None,
                "relax_ranking": relax_scores[:3],
            })

    holonomy_flag = len(bad_cycles) > 0 or dim_H0 == 0

    gaps = []
    for em in edge_maps:
        rs = features[em.source][:d]
        rt = features[em.target][:d]
        if rs.size < d:
            rs = np.pad(rs, (0, d - rs.size))
        if rt.size < d:
            rt = np.pad(rt, (0, d - rt.size))
        diff = em.matrix @ rt - rs
        gaps.append({
            "source": em.source, "target": em.target, "relation": em.relation,
            "disagreement": float(np.dot(diff, diff)), "theta": em.theta,
        })
    gaps.sort(key=lambda g: g["disagreement"], reverse=True)
    for i, g in enumerate(gaps, 1):
        g["rank"] = i

    return {
        "energy": energy, "dim_H0": dim_H0, "dim_H1": dim_H1, "rank_delta": rank,
        "holonomy_flag": holonomy_flag, "bad_cycles": bad_cycles, "gaps": gaps,
        "n_nodes": n, "n_edges": m,
    }

"""CRC repair class + proposals + relative (depends on crc_part_a)."""
from __future__ import annotations
from typing import Any
import numpy as np
from crc_part_a import *  # noqa: F401,F403
from crc_part_a import EdgeMap, rotation, CRCReport, analyze_connection, connected_components  # noqa: F401


def repair_class_from(analysis: dict[str, Any]) -> str:
    E = analysis["energy"]
    h0 = analysis["dim_H0"]
    hol = analysis["holonomy_flag"]
    if E < 1e-8 and not hol:
        return "consistent"
    if hol and h0 == 0 and E > 1e-8:
        return "structural"
    if hol and E > 1e-8:
        return "mixed"
    if E > 1e-8:
        return "statistical"
    return "consistent"


def proposals_for(analysis: dict[str, Any], repair_class: str) -> list[dict[str, Any]]:
    props: list[dict[str, Any]] = []
    if repair_class in ("statistical", "mixed", "consistent"):
        for g in analysis["gaps"][:5]:
            if g["disagreement"] < 1e-12:
                continue
            props.append({
                "action": "realign",
                "source": g["source"],
                "target": g["target"],
                "score": g["disagreement"],
                "rationale": f"Statistical gap; realign stalks (ΔE≈{g['disagreement']:.4f})",
            })
            props.append({
                "action": "drop_edge",
                "source": g["source"],
                "target": g["target"],
                "score": g["disagreement"] * 0.95,
                "rationale": "Drop inconsistent link",
            })
    if repair_class in ("structural", "mixed"):
        for bc in analysis["bad_cycles"]:
            best = bc.get("best_relax")
            if best:
                props.append({
                    "action": "relax_restriction",
                    "source": best["source"],
                    "target": best["target"],
                    "score": best["reduction"] + 10.0,
                    "rationale": (
                        f"Kill holonomy on cycle {bc['cycle_id']}: "
                        f"relax map θ→0 reduces deviation by {best['reduction']:.4f}"
                    ),
                })
            props.append({
                "action": "grow_structure",
                "source": bc["edges"][0]["source"] if bc["edges"] else "?",
                "target": bc["edges"][-1]["target"] if bc["edges"] else "?",
                "score": bc["holonomy_deviation"] + 9.0,
                "rationale": (
                    f"Structural obstruction on cycle {bc['cycle_id']} "
                    f"(holonomy dev={bc['holonomy_deviation']:.4f})"
                ),
            })
    seen: dict[tuple, dict] = {}
    for p in props:
        key = (p["action"], p["source"], p["target"])
        if key not in seen or p["score"] > seen[key]["score"]:
            seen[key] = p
    return sorted(seen.values(), key=lambda p: p["score"], reverse=True)


def relative_crc(
    nodes: list[str],
    edge_maps: list[EdgeMap],
    features: dict[str, np.ndarray],
    reference: dict[str, np.ndarray],
    d: int = 2,
) -> dict[str, Any]:
    self_a = analyze_connection(nodes, edge_maps, features, d)
    ref_a = analyze_connection(nodes, edge_maps, reference, d)
    mismatch = 0.0
    for n in nodes:
        xf = features[n][:d]
        rf = reference[n][:d]
        if xf.size < d:
            xf = np.pad(xf, (0, d - xf.size))
        if rf.size < d:
            rf = np.pad(rf, (0, d - rf.size))
        mismatch += float(np.sum((xf - rf) ** 2))

    self_E, ref_E = self_a["energy"], ref_a["energy"]
    if mismatch < 1e-6 and self_E < 1e-6:
        status = "aligned_with_reference"
    elif self_E < 1e-6 and mismatch > 1e-4:
        status = "self_consistent_wrong_vs_ledger"
    elif self_E > 1e-4 and mismatch > 1e-4:
        status = "inconsistent_and_mismatched"
    elif self_E > 1e-4 and mismatch < 1e-4:
        status = "matches_ledger_but_internal_gaps"
    else:
        status = "partial"

    return {
        "status": status,
        "self_energy": self_E,
        "reference_energy": ref_E,
        "grounding_mismatch": mismatch,
        "self_repair_class": repair_class_from(self_a),
        "reference_repair_class": repair_class_from(ref_a),
        "interpretation": {
            "self_consistent_wrong_vs_ledger": "Internally harmonic but disagrees with ledger",
            "aligned_with_reference": "Self and ledger agree",
            "inconsistent_and_mismatched": "Broken internally and vs ledger",
            "matches_ledger_but_internal_gaps": "Matches ledger but sheaf energy high",
            "partial": "Intermediate",
        }.get(status, status),
    }


def crc_constant_graph(
    nodes: list[str],
    edges: list[tuple[str, str, str]],
    features: dict[str, np.ndarray],
    d: int,
    reference: dict[str, np.ndarray] | None = None,
) -> CRCReport:
    edge_maps = [EdgeMap(source=s, target=t, relation=rel, theta=0.0) for s, t, rel in edges]
    feats = {}
    for n in nodes:
        v = np.asarray(features[n], dtype=float).ravel()
        if v.size < d:
            v = np.pad(v, (0, d - v.size))
        feats[n] = v[:d]
    analysis = analyze_connection(nodes, edge_maps, feats, d=2) if d == 2 else {
        "energy": 0.0, "dim_H0": d, "dim_H1": 0, "holonomy_flag": False,
        "bad_cycles": [], "gaps": [], "n_nodes": len(nodes), "n_edges": len(edges),
    }
    rc = repair_class_from(analysis)
    props = proposals_for(analysis, rc)
    rel = {"status": "no_reference"}
    if reference is not None and d == 2:
        ref2 = {}
        for n in nodes:
            v = np.asarray(reference[n], dtype=float).ravel()
            if v.size < 2:
                v = np.pad(v, (0, 2 - v.size))
            ref2[n] = v[:2]
        rel = relative_crc(nodes, edge_maps, feats, ref2, d=2)
    n_e = max(analysis["n_edges"], 1)
    return CRCReport(
        energy=analysis["energy"],
        normalized_energy=analysis["energy"] / n_e,
        repair_class=rc,
        holonomy_flag=analysis["holonomy_flag"],
        dim_H0=analysis["dim_H0"],
        dim_H1=analysis["dim_H1"],
        bad_cycles=analysis["bad_cycles"],
        gaps=analysis["gaps"],
        proposals=props,
        relative=rel,
        n_nodes=analysis["n_nodes"],
        n_edges=analysis["n_edges"],
    )

"""
Cycle-space equations over R/2πZ for abelian (U(1)/SO(2)) connections.

Hol_γ(θ) = exp(i * (C θ)_γ). Flatness: C θ ≡ 0 (mod 2π).

DELETE (FES): remove edges so no cycles remain.
RELAX (surgery): keep edges, set some θ_e = 0, solve C θ ≡ 0 (mod 2π).
These are NOT the same integer programs — see SURGERY_VS_FES.md.
"""

from __future__ import annotations

from typing import Any
import numpy as np
from itertools import combinations

try:
    from holonomy_cheeger import fundamental_cycles, rotation
except ImportError:
    from crc import rotation  # type: ignore
    fundamental_cycles = None  # type: ignore


def cycle_basis_matrix(
    nodes: list[str], edges: list[tuple[str, str]]
) -> tuple[np.ndarray, list]:
    if fundamental_cycles is None:
        return np.zeros((0, len(edges))), []
    cycles = fundamental_cycles(nodes, edges)
    m = len(edges)
    edge_index = {frozenset(e): i for i, e in enumerate(edges)}
    C = np.zeros((len(cycles), m), dtype=float)
    for ci, cyc in enumerate(cycles):
        for a, b in cyc:
            key = frozenset([a, b])
            if key not in edge_index:
                continue
            j = edge_index[key]
            s, t = edges[j]
            C[ci, j] += 1.0 if (a, b) == (s, t) else -1.0
    return C, cycles


def holonomy_angles(theta: np.ndarray, C: np.ndarray) -> np.ndarray:
    raw = C @ theta
    return (raw + np.pi) % (2 * np.pi) - np.pi


def is_flat(theta: np.ndarray, C: np.ndarray, tol: float = 1e-8) -> bool:
    return bool(np.all(np.abs(holonomy_angles(theta, C)) < tol))


def min_relax_set(
    nodes: list[str],
    edges: list[tuple[str, str]],
    theta: np.ndarray,
) -> dict[str, Any]:
    """Minimum edges to zero so Cθ ≡ 0 (mod 2π). Exact for small graphs."""
    C, cycles = cycle_basis_matrix(nodes, edges)
    if len(cycles) == 0:
        return {"edits": [], "n_edits": 0, "flat_after": True, "optimal": True}
    nonzero = [i for i, t in enumerate(theta) if abs(t) > 1e-12]
    best = None
    for k in range(0, len(nonzero) + 1):
        for combo in combinations(nonzero, k):
            theta2 = theta.copy()
            for i in combo:
                theta2[i] = 0.0
            if is_flat(theta2, C):
                best = list(combo)
                break
        if best is not None:
            break
    return {
        "edits": best or [],
        "n_edits": len(best or []),
        "flat_after": best is not None,
        "optimal": True,
        "note": "relax ≠ feedback-edge-set; see research/SURGERY_VS_FES.md",
    }

"""
Holonomy calculation methods + Cheeger constant bound.

Classical only. Cheeger is optional scale-out diagnostic (not repair class).
"""

from __future__ import annotations

from typing import Any
import numpy as np


def rotation(theta: float) -> np.ndarray:
    c, s = np.cos(theta), np.sin(theta)
    return np.array([[c, -s], [s, c]], dtype=float)


def spanning_forest_parent(
    nodes: list[str], edges: list[tuple[str, str]]
) -> dict[str, str | None]:
    adj: dict[str, list[str]] = {n: [] for n in nodes}
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)
    parent: dict[str, str | None] = {n: None for n in nodes}
    seen: set[str] = set()
    for root in nodes:
        if root in seen:
            continue
        queue = [root]
        seen.add(root)
        parent[root] = None
        while queue:
            u = queue.pop(0)
            for w in adj[u]:
                if w not in seen:
                    seen.add(w)
                    parent[w] = u
                    queue.append(w)
    return parent


def fundamental_cycles(
    nodes: list[str], edges: list[tuple[str, str]]
) -> list[list[tuple[str, str]]:
    parent = spanning_forest_parent(nodes, edges)
    tree_edges = set()
    for v, p in parent.items():
        if p is not None:
            tree_edges.add(frozenset((p, v)))

    def path_to_root(v: str) -> list[str]:
        chain = [v]
        while parent[chain[-1]] is not None:
            chain.append(parent[chain[-1]])  # type: ignore
        return chain

    cycles: list[list[tuple[str, str]]] = []
    for u, v in edges:
        if frozenset((u, v)) in tree_edges:
            continue
        pu, pv = path_to_root(u), path_to_root(v)
        set_pu = set(pu)
        lca = next(x for x in pv if x in set_pu)
        path_u = []
        x = u
        while x != lca:
            p = parent[x]
            assert p is not None
            path_u.append((x, p))
            x = p
        stack = []
        x = v
        while x != lca:
            p = parent[x]
            assert p is not None
            stack.append((p, x))
            x = p
        path_v_rev = list(reversed(stack))
        cyc = path_u + path_v_rev + [(v, u)]
        cycles.append(cyc)
    return cycles


def holonomy_product(
    cycle: list[tuple[str, str]],
    maps: dict[tuple[str, str], np.ndarray],
    d: int = 2,
) -> tuple[np.ndarray, float]:
    H = np.eye(d)
    for u, v in cycle:
        if (u, v) in maps:
            M = maps[(u, v)]
        elif (v, u) in maps:
            M = np.linalg.inv(maps[(v, u)])
        else:
            M = np.eye(d)
        H = M @ H
    dev = float(np.linalg.norm(H - np.eye(d)))
    return H, dev


def holonomy_report(
    nodes: list[str],
    edge_maps: list[tuple[str, str, float]],
    eps: float = 1e-8,
) -> dict[str, Any]:
    edges = [(a, b) for a, b, _ in edge_maps]
    maps = {(a, b): rotation(th) for a, b, th in edge_maps}
    cycles = fundamental_cycles(nodes, edges)
    bad = []
    for cyc in cycles:
        H, dev = holonomy_product(cyc, maps)
        if dev > eps:
            bad.append({"cycle": cyc, "dev": dev, "tr": float(np.trace(H))})
    return {
        "n_cycles": len(cycles),
        "holonomy_flag": len(bad) > 0,
        "bad_cycles": bad,
    }


def graph_laplacian(
    nodes: list[str], edges: list[tuple[str, str]]
) -> np.ndarray:
    n = len(nodes)
    idx = {nd: i for i, nd in enumerate(nodes)}
    L = np.zeros((n, n))
    for u, v in edges:
        i, j = idx[u], idx[v]
        L[i, i] += 1
        L[j, j] += 1
        L[i, j] -= 1
        L[j, i] -= 1
    return L


def cheeger_from_fiedler(
    nodes: list[str], edges: list[tuple[str, str]]
) -> dict[str, Any]:
    L = graph_laplacian(nodes, edges)
    evals, evecs = np.linalg.eigh(L)
    pos = np.where(evals > 1e-10)[0]
    if len(pos) == 0:
        return {"lambda1": 0.0, "h_upper_sqrt": 0.0, "cut": 0, "partition": []}
    i1 = pos[0]
    lam1 = float(evals[i1])
    fiedler = evecs[:, i1]
    side = fiedler >= 0
    S = {nodes[i] for i in range(len(nodes)) if side[i]}
    Sc = set(nodes) - S
    cut = sum(1 for u, v in edges if (u in S) != (v in S))
    h_proxy = cut / max(min(len(S), len(Sc)), 1)
    return {
        "lambda1": lam1,
        "cheeger_upper_sqrt2lam": float(np.sqrt(2 * lam1)),
        "cut_edges": cut,
        "partition_sizes": [len(S), len(Sc)],
        "h_proxy": h_proxy,
        "note": "λ₁/2 ≤ h ≤ √(2λ₁) form depends on normalization; proxy is combinatorial",
    }


if __name__ == "__main__":
    nodes = ["A", "B", "C"]
    emaps = [("A", "B", np.pi / 2), ("B", "C", np.pi / 2), ("C", "A", np.pi / 2)]
    print("PENROSE", holonomy_report(nodes, emaps))
    nodes2 = [f"L{i}" for i in range(4)] + [f"R{i}" for i in range(4)]
    edges2 = [
        ("L0", "L1"), ("L1", "L2"), ("L2", "L3"), ("L3", "L0"),
        ("R0", "R1"), ("R1", "R2"), ("R2", "R3"), ("R3", "R0"),
        ("L0", "R0"),
    ]
    print("CHEEGER", cheeger_from_fiedler(nodes2, edges2))

"""CSV multi-source ingest → CRC."""
from __future__ import annotations
from pathlib import Path
from typing import Any
import csv
import numpy as np
from crc import EdgeMap, crc_connection

def load_csv(path: str | Path) -> list[dict[str, str]]:
    with open(path, newline="", encoding="utf-8") as f:
        return list(csv.DictReader(f))

def rows_to_graph(
    tables: dict[str, list[dict[str, str]]],
    *,
    feature_cols: tuple[str, ...] = ("risk_tier", "kyc_status"),
    sot_system: str | None = None,
) -> tuple[list[str], list[EdgeMap], dict[str, np.ndarray], dict[str, np.ndarray] | None]:
    nodes: list[str] = []
    feats: dict[str, np.ndarray] = {}
    by_entity: dict[str, list[str]] = {}
    for sys_name, rows in tables.items():
        for row in rows:
            eid = row.get("entity_id") or row.get("id")
            if not eid:
                continue
            nid = f"{sys_name}:{eid}"
            nodes.append(nid)
            vec = []
            for c in feature_cols:
                try:
                    vec.append(float(row.get(c, 0) or 0))
                except ValueError:
                    vec.append(0.0)
            feats[nid] = np.array(vec, dtype=float)
            by_entity.setdefault(eid, []).append(nid)
    maps: list[EdgeMap] = []
    for eid, nids in by_entity.items():
        for i, a in enumerate(nids):
            for b in nids[i + 1 :]:
                maps.append(EdgeMap(a, b, "same_person", 0.0))
    reference = None
    if sot_system:
        reference = {n: feats[n].copy() for n in nodes if n.startswith(sot_system + ":")}
        # expand: for every entity, SoT node features as ref for all systems
        ref_full = {}
        for eid, nids in by_entity.items():
            sot_nid = f"{sot_system}:{eid}"
            if sot_nid in feats:
                for n in nids:
                    ref_full[n] = feats[sot_nid].copy()
        reference = ref_full if ref_full else reference
    return nodes, maps, feats, reference

def run_crc_on_tables(
    tables: dict[str, list[dict[str, str]]],
    *,
    sot_system: str | None = None,
    feature_cols: tuple[str, ...] = ("risk_tier", "kyc_status"),
) -> dict[str, Any]:
    nodes, maps, feats, reference = rows_to_graph(
        tables, feature_cols=feature_cols, sot_system=sot_system
    )
    full = crc_connection(nodes, maps, feats, reference=reference)
    per_entity = {}
    entities = set()
    for n in nodes:
        if ":" in n:
            entities.add(n.split(":", 1)[1])
    for eid in entities:
        enodes = [n for n in nodes if n.endswith(":" + eid) or n.split(":")[-1] == eid]
        emaps = [m for m in maps if m.source in enodes and m.target in enodes]
        efeats = {n: feats[n] for n in enodes if n in feats}
        eref = {n: reference[n] for n in enodes if reference and n in reference} or None
        if len(efeats) < 1:
            continue
        r = crc_connection(enodes, emaps, efeats, reference=eref)
        per_entity[eid] = {
            "repair_class": r.repair_class,
            "relative": r.relative.get("status") if r.relative else None,
            "energy": r.energy,
            "n_systems": len(enodes),
            "holonomy_flag": r.holonomy_flag,
        }
    return {
        "full": {
            "repair_class": full.repair_class,
            "energy": full.energy,
            "holonomy_flag": full.holonomy_flag,
            "relative": full.relative,
        },
        "per_entity": per_entity,
    }

"""
Ledger write-back policy engine.

Decision: NOT an auto-repair path.
  - Relative CRC flags self_consistent_wrong_vs_ledger
  - Write-back is a *policy action* with an explicit key
  - Default: refuse
"""

from __future__ import annotations

from dataclasses import dataclass
from typing import Any


@dataclass
class WriteBackDecision:
    allowed: bool
    reason: str
    actions: list[dict[str, Any]]


def evaluate_write_back(
    crc_report: dict[str, Any],
    *,
    policy_key: str | None = None,
    allow_realign: bool = False,
    allow_drop: bool = False,
) -> WriteBackDecision:
    """Refuse by default. Require explicit policy_key and flags."""
    if not policy_key:
        return WriteBackDecision(
            allowed=False,
            reason="missing policy_key — write-back refused",
            actions=[],
        )
    if policy_key != "FOUNDER_WRITEBACK_YES":
        return WriteBackDecision(
            allowed=False,
            reason="invalid policy_key",
            actions=[],
        )
    relative = (crc_report.get("relative") or {})
    status = relative.get("status") if isinstance(relative, dict) else relative
    actions: list[dict[str, Any]] = []
    if status == "self_consistent_wrong_vs_ledger":
        if allow_realign:
            actions.append({"type": "realign_to_sot", "scope": "flagged_entities"})
        if allow_drop:
            actions.append({"type": "drop_non_sot_edges", "scope": "flagged_entities"})
        if not actions:
            return WriteBackDecision(
                allowed=False,
                reason="relative fraud detected but no allow_realign/allow_drop flags",
                actions=[],
            )
        return WriteBackDecision(
            allowed=True,
            reason="policy_key valid; relative fraud with explicit allow flags",
            actions=actions,
        )
    return WriteBackDecision(
        allowed=False,
        reason=f"no write-back path for status={status}",
        actions=[],
    )

"""
Proposal ranker bake-off:
  R1 energy:        rank edges by ||x_t - x_s||^2
  R2 one-step ΔE:   rank by energy drop if edge dropped
  R3 Δc_S proxy:    rank by contribution to cycle obstruction

Report recovery@k on planted suites.
"""

from __future__ import annotations

from typing import Any
import numpy as np


def rank_by_energy(gaps: dict[str, float]) -> list[tuple[str, float]]:
    return sorted(gaps.items(), key=lambda kv: -kv[1])


def rank_by_delta_e(
    nodes: list[str],
    edges: list[tuple[str, str]],
    energy_fn,
) -> list[tuple[str, float]]:
    """One-step ΔE if edge removed (higher = more useful to drop)."""
    base = energy_fn(edges)
    scores = []
    for i, e in enumerate(edges):
        remaining = edges[:i] + edges[i + 1 :]
        scores.append((f"{e[0]}->{e[1]}", base - energy_fn(remaining)))
    return sorted(scores, key=lambda kv: -kv[1])


def recovery_at_k(
    ranked: list[tuple[str, float]],
    true_bad: set[str],
    k: int,
) -> float:
    top = {e for e, _ in ranked[:k]}
    if not true_bad:
        return 1.0
    return len(top & true_bad) / len(true_bad)


def bakeoff_report(
    gaps: dict[str, float],
    true_bad: set[str],
    ks: tuple[int, ...] = (1, 3, 5),
) -> dict[str, Any]:
    ranked = rank_by_energy(gaps)
    return {
        "ranker": "energy",
        "recovery": {f"@{k}": recovery_at_k(ranked, true_bad, k) for k in ks},
        "ranked": ranked[:10],
    }

"""
Apply-repair + re-measure loop.

Rules:
  1. Statistical ops (realign, drop_edge) may auto-apply in a loop.
  2. Structural ops (relax_restriction) may auto-apply; grow_structure is propose-only.
  3. Relative-fraud / ledger write-back NEVER auto-applies without policy_key.
  4. Every apply returns before/after consistency so the caller can stop on plateau.
"""

from __future__ import annotations

from copy import deepcopy
from dataclasses import dataclass
from typing import Any
import numpy as np

from crc import EdgeMap, crc_connection, CRCReport, rotation


@dataclass
class GraphState:
    nodes: list[str]
    maps: list[EdgeMap]
    feats: dict[str, np.ndarray]
    reference: dict[str, np.ndarray] | None = None

    def clone(self) -> "GraphState":
        return GraphState(
            nodes=list(self.nodes),
            maps=[EdgeMap(m.source, m.target, m.relation, m.theta) for m in self.maps],
            feats={k: v.copy() for k, v in self.feats.items()},
            reference={k: v.copy() for k, v in self.reference.items()} if self.reference else None,
        )


def measure(state: GraphState) -> CRCReport:
    return crc_connection(state.nodes, state.maps, state.feats, reference=state.reference)


def apply_realign(state: GraphState, source: str, target: str) -> GraphState:
    """Set both endpoints to the mean of their features (statistical realign)."""
    s = state.clone()
    if source in s.feats and target in s.feats:
        mean = 0.5 * (s.feats[source] + s.feats[target])
        s.feats[source] = mean.copy()
        s.feats[target] = mean.copy()
    return s


def apply_drop_edge(state: GraphState, source: str, target: str) -> GraphState:
    s = state.clone()
    s.maps = [m for m in s.maps if not (m.source == source and m.target == target)]
    return s


def apply_relax(state: GraphState, source: str, target: str) -> GraphState:
    """Set theta=0 on the edge (structural relax)."""
    s = state.clone()
    new_maps = []
    for m in s.maps:
        if m.source == source and m.target == target:
            new_maps.append(EdgeMap(m.source, m.target, m.relation, 0.0))
        else:
            new_maps.append(m)
    s.maps = new_maps
    return s


def repair_step(state: GraphState, proposal: dict[str, Any]) -> tuple[GraphState, CRCReport, CRCReport]:
    before = measure(state)
    action = proposal.get("action")
    src, tgt = proposal.get("source"), proposal.get("target")
    if action == "realign":
        after_state = apply_realign(state, src, tgt)
    elif action == "drop_edge":
        after_state = apply_drop_edge(state, src, tgt)
    elif action == "relax_restriction":
        after_state = apply_relax(state, src, tgt)
    else:
        after_state = state.clone()
    after = measure(after_state)
    return after_state, before, after


def auto_loop(
    state: GraphState,
    *,
    max_steps: int = 5,
    allow_structural: bool = True,
) -> dict[str, Any]:
    history = []
    cur = state.clone()
    for step in range(max_steps):
        report = measure(cur)
        if report.repair_class == "consistent" and report.energy < 1e-8:
            break
        props = [p for p in report.proposals if p["action"] != "grow_structure"]
        if not allow_structural:
            props = [p for p in props if p["action"] != "relax_restriction"]
        if not props:
            break
        # Never auto write-back relative fraud
        if report.relative.get("status") == "self_consistent_wrong_vs_ledger":
            history.append({"step": step, "stopped": "relative_fraud_requires_policy"})
            break
        cur, before, after = repair_step(cur, props[0])
        history.append({
            "step": step,
            "action": props[0]["action"],
            "before_energy": before.energy,
            "after_energy": after.energy,
            "after_class": after.repair_class,
        })
        if after.energy >= before.energy - 1e-12:
            break
    final = measure(cur)
    return {"history": history, "final": final.to_dict()}

"""
Minimal knowledge-integrity core.

Public language: energy, gaps, proposals.
Internal: discrete cellular sheaf with identity restriction maps on R^d stalks.

  (δx)_e = x_t - x_s
  energy E(x) = ||δx||^2
"""

from __future__ import annotations

from dataclasses import dataclass, field
from typing import Any
import numpy as np


@dataclass
class Graph:
    nodes: list[str]
    edges: list[tuple[str, str, str]]  # (source, target, relation)
    features: dict[str, np.ndarray]
    feature_dim: int = 2

    @classmethod
    def from_dict(cls, payload: dict[str, Any]) -> "Graph":
        d = int(payload.get("feature_dim", 2))
        nodes = []
        features = {}
        for n in payload["nodes"]:
            nid = n["id"] if isinstance(n, dict) else n
            nodes.append(nid)
            if isinstance(n, dict) and "features" in n:
                features[nid] = np.asarray(n["features"], dtype=float)
            else:
                features[nid] = np.zeros(d)
        edges = []
        for e in payload["edges"]:
            edges.append((e["source"], e["target"], e.get("relation", "related")))
        return cls(nodes=nodes, edges=edges, features=features, feature_dim=d)


def energy(g: Graph) -> float:
    d = g.feature_dim
    total = 0.0
    for s, t, _ in g.edges:
        xs = g.features[s][:d]
        xt = g.features[t][:d]
        if xs.size < d:
            xs = np.pad(xs, (0, d - xs.size))
        if xt.size < d:
            xt = np.pad(xt, (0, d - xt.size))
        diff = xt - xs
        total += float(np.dot(diff, diff))
    return total


def gaps(g: Graph) -> list[dict[str, Any]]:
    d = g.feature_dim
    out = []
    for s, t, rel in g.edges:
        xs = g.features[s][:d]
        xt = g.features[t][:d]
        if xs.size < d:
            xs = np.pad(xs, (0, d - xs.size))
        if xt.size < d:
            xt = np.pad(xt, (0, d - xt.size))
        diff = xt - xs
        out.append({
            "source": s, "target": t, "relation": rel,
            "disagreement": float(np.dot(diff, diff)),
        })
    out.sort(key=lambda z: -z["disagreement"])
    return out


def consistency(g: Graph) -> dict[str, Any]:
    E = energy(g)
    gs = gaps(g)
    return {
        "energy": E,
        "gaps": gs,
        "consistent": E < 1e-8,
        "n_nodes": len(g.nodes),
        "n_edges": len(g.edges),
    }

"""Minimal restriction edits (surgery) to restore gluing."""
from __future__ import annotations
from typing import Any
import numpy as np
from crc import EdgeMap, crc_connection


def propose_surgery(
    nodes: list[str],
    maps: list[EdgeMap],
    feats: dict[str, np.ndarray],
) -> dict[str, Any]:
    """If structural, rank edges to relax (theta→0) by holonomy reduction."""
    r = crc_connection(nodes, maps, feats)
    if r.repair_class not in ("structural", "mixed"):
        return {"needed": False, "repair_class": r.repair_class, "edits": []}
    edits = []
    for bc in r.bad_cycles:
        best = bc.get("best_relax")
        if best:
            edits.append({
                "source": best["source"],
                "target": best["target"],
                "action": "relax_theta_to_0",
                "reduction": best["reduction"],
                "cycle_id": bc.get("cycle_id"),
            })
    edits.sort(key=lambda e: -e.get("reduction", 0))
    return {
        "needed": True,
        "repair_class": r.repair_class,
        "edits": edits,
        "certificate": "post-edit: re-run crc_connection; expect holonomy_flag False or reduced",
    }


def apply_surgery(
    maps: list[EdgeMap],
    edits: list[dict[str, Any]],
) -> list[EdgeMap]:
    keys = {(e["source"], e["target"]) for e in edits}
    out = []
    for m in maps:
        if (m.source, m.target) in keys:
            out.append(EdgeMap(m.source, m.target, m.relation, 0.0))
        else:
            out.append(m)
    return out

